1	import NextAuth from "next-auth";
2	import Credentials from "next-auth/providers/credentials";
3	import type { UserRole } from "@prisma/client";
4	import { z } from "zod";
5	import { authenticateUser } from "@/lib/auth-service";
6	
7	// Credentials sign-in requires the JWT session strategy (no DB session table).
8	// AUTH_SECRET is read from the environment automatically.
9	const credentialsSchema = z.object({
10	  email: z.string().email(),
11	  password: z.string().min(1),
12	});
13	
14	export const { handlers, signIn, signOut, auth } = NextAuth({
15	  session: { strategy: "jwt" },
16	  trustHost: true,
17	  pages: {
18	    signIn: "/login",
19	  },
20	  providers: [
21	    Credentials({
22	      credentials: {
23	        email: { label: "Email", type: "email" },
24	        password: { label: "Password", type: "password" },
25	      },
26	      async authorize(rawCredentials) {
27	        const parsed = credentialsSchema.safeParse(rawCredentials);
28	        if (!parsed.success) return null;
29	        const { email, password } = parsed.data;
30	        return authenticateUser(email, password);
31	      },
32	    }),
33	  ],
34	  callbacks: {
35	    // Persist id + role into the JWT on sign-in.
36	    jwt({ token, user }) {
37	      if (user) {
38	        token.id = user.id as string;
39	        token.role = (user as { role: UserRole }).role;
40	      }
41	      return token;
42	    },
43	    // Expose id + role on the session for server-side authorization.
44	    session({ session, token }) {
45	      if (session.user) {
46	        session.user.id = token.id as string;
47	        session.user.role = token.role as UserRole;
48	      }
49	      return session;
50	    },
51	  },
52	});
