1	import type { UserRole } from "@prisma/client";
2	import { prisma } from "@/lib/prisma";
3	import { verifyPassword } from "@/lib/password";
4	import { logger } from "@/lib/logger";
5	import {
6	  ACCOUNT_LOCKOUT_DURATION_MS,
7	  MAX_FAILED_LOGIN_ATTEMPTS_BEFORE_LOCKOUT,
8	} from "@/lib/constants";
9	
10	export type AuthenticatedUser = {
11	  id: string;
12	  email: string;
13	  name: string;
14	  role: UserRole;
15	  image: string | null;
16	};
17	
18	/**
19	 * Verify credentials with brute-force protection (OWASP-AUTH-001 / RATELIMIT-001).
20	 * Returns a safe user object on success, or null on any failure. Failure is
21	 * intentionally indistinguishable to the caller to avoid user enumeration.
22	 */
23	export async function authenticateUser(
24	  email: string,
25	  password: string,
26	): Promise<AuthenticatedUser | null> {
27	  const normalizedEmail = email.trim().toLowerCase();
28	  const user = await prisma.user.findUnique({ where: { email: normalizedEmail } });
29	
30	  if (!user) {
31	    logger.warn("auth.login.failed", { email: normalizedEmail, reason: "no_such_user" });
32	    return null;
33	  }
34	
35	  if (user.lockedUntil && user.lockedUntil > new Date()) {
36	    logger.warn("auth.login.blocked", { userId: user.id, reason: "account_locked" });
37	    return null;
38	  }
39	
40	  const passwordMatches = await verifyPassword(password, user.passwordHash);
41	  if (!passwordMatches) {
42	    await registerFailedAttempt(user.id, user.failedLoginAttempts);
43	    logger.warn("auth.login.failed", { userId: user.id, reason: "bad_password" });
44	    return null;
45	  }
46	
47	  await resetLoginState(user.id);
48	  logger.info("auth.login.success", { userId: user.id, role: user.role });
49	
50	  return {
51	    id: user.id,
52	    email: user.email,
53	    name: user.name,
54	    role: user.role,
55	    image: user.image,
56	  };
57	}
58	
59	async function registerFailedAttempt(userId: string, currentAttempts: number): Promise<void> {
60	  const nextAttempts = currentAttempts + 1;
61	  const shouldLock = nextAttempts >= MAX_FAILED_LOGIN_ATTEMPTS_BEFORE_LOCKOUT;
62	  await prisma.user.update({
63	    where: { id: userId },
64	    data: {
65	      failedLoginAttempts: nextAttempts,
66	      lockedUntil: shouldLock
67	        ? new Date(Date.now() + ACCOUNT_LOCKOUT_DURATION_MS)
68	        : null,
69	    },
70	  });
71	  if (shouldLock) {
72	    logger.warn("auth.account.locked", { userId, attempts: nextAttempts });
73	  }
74	}
75	
76	async function resetLoginState(userId: string): Promise<void> {
77	  await prisma.user.update({
78	    where: { id: userId },
79	    data: { failedLoginAttempts: 0, lockedUntil: null },
80	  });
81	}
