1	// Simple in-process sliding-window rate limiter.
2	// NOTE (OWASP-RATELIMIT-001): in-memory state is only correct for a single
3	// instance. A horizontally-scaled deployment must back this with a shared store
4	// (Redis/Upstash). Kept in-memory here to stay zero-dependency for local dev.
5	
6	const hits = new Map<string, number[]>();
7	
8	export type RateLimitResult = {
9	  allowed: boolean;
10	  remaining: number;
11	  retryAfterSeconds: number;
12	};
13	
14	export function checkRateLimit(
15	  key: string,
16	  limit: number,
17	  windowMs: number,
18	): RateLimitResult {
19	  const now = Date.now();
20	  const windowStart = now - windowMs;
21	  const timestamps = (hits.get(key) ?? []).filter((t) => t > windowStart);
22	
23	  if (timestamps.length >= limit) {
24	    const oldest = timestamps[0];
25	    const retryAfterSeconds = Math.ceil((oldest + windowMs - now) / 1000);
26	    hits.set(key, timestamps);
27	    return { allowed: false, remaining: 0, retryAfterSeconds };
28	  }
29	
30	  timestamps.push(now);
31	  hits.set(key, timestamps);
32	  return { allowed: true, remaining: limit - timestamps.length, retryAfterSeconds: 0 };
33	}
