1	// Minimal structured (JSON) logger with sensitive-field scrubbing.
2	// Satisfies OWASP-LOG-001 / BP-LOG-001: never log secrets, use discrete fields,
3	// never build messages by string concatenation of untrusted data.
4	
5	type LogLevel = "debug" | "info" | "warn" | "error";
6	
7	const SENSITIVE_KEYS = new Set([
8	  "password",
9	  "passwordhash",
10	  "token",
11	  "secret",
12	  "authorization",
13	  "cookie",
14	  "apikey",
15	  "api_key",
16	  "openai_api_key",
17	  "cvv",
18	  "ssn",
19	  "card_number",
20	]);
21	
22	function scrub(fields: Record<string, unknown>): Record<string, unknown> {
23	  const out: Record<string, unknown> = {};
24	  for (const [key, value] of Object.entries(fields)) {
25	    out[key] = SENSITIVE_KEYS.has(key.toLowerCase()) ? "[REDACTED]" : value;
26	  }
27	  return out;
28	}
29	
30	function emit(level: LogLevel, message: string, fields: Record<string, unknown> = {}) {
31	  const entry = {
32	    level,
33	    message,
34	    timestamp: new Date().toISOString(),
35	    ...scrub(fields),
36	  };
37	  const line = JSON.stringify(entry);
38	  if (level === "error") console.error(line);
39	  else if (level === "warn") console.warn(line);
40	  else console.log(line);
41	}
42	
43	export const logger = {
44	  debug: (message: string, fields?: Record<string, unknown>) =>
45	    process.env.NODE_ENV === "development" && emit("debug", message, fields),
46	  info: (message: string, fields?: Record<string, unknown>) => emit("info", message, fields),
47	  warn: (message: string, fields?: Record<string, unknown>) => emit("warn", message, fields),
48	  error: (message: string, fields?: Record<string, unknown>) => emit("error", message, fields),
49	};
